def get_benchmark_skills_gap_catalog() -> List[BenchmarkSkillsGapRecord]:
    """Return complete benchmark_skills_gap registry."""
    return REGISTRY_BENCHMARK_SKILLS_GAP


def query_benchmark_skills_gap_by_difficulty(difficulty_level: str) -> List[BenchmarkSkillsGapRecord]:
    """Filter benchmark_skills_gap elements matching difficulty."""
    return [item for item in REGISTRY_BENCHMARK_SKILLS_GAP if item.difficulty == difficulty_level]


def calculate_benchmark_skills_gap_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_BENCHMARK_SKILLS_GAP)

